// Regenerates src/data/guides/index.ts from the JSON files in that folder.
import { readdirSync, writeFileSync } from "fs";
import path from "path";

const dir = path.join(process.cwd(), "src/data/guides");
const files = readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
const ident = (f) => "g_" + f.replace(/\.json$/, "").replace(/[^a-z0-9]/gi, "_");
const src = `// Curated guides: researched by agents against official docs, then spot-checked
// by hand (see each guide's meta.verification). Generated by scripts/index-guides.mjs.
import type { StoredGuide } from "@/lib/schema";
${files.map((f) => `import ${ident(f)} from "./${f}";`).join("\n")}

export const curated = [${files.map(ident).join(", ")}] as unknown as StoredGuide[];
`;
writeFileSync(path.join(dir, "index.ts"), src);
console.log(`indexed ${files.length} guides`);
